const sessionId = typeof $json.sessionId === 'string' ? $json.sessionId.trim() : '';
const requestId = typeof $json.requestId === 'string' ? $json.requestId.trim() : '';
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const ALLOWED = ['all', 'ready', 'uncertain', 'accepted', 'executed'];
const raw = typeof $json.filter === 'string' ? $json.filter.trim().toLowerCase() : '';
const filter = ALLOWED.includes(raw) ? raw : 'all';
const error = (uuidPattern.test(sessionId) && uuidPattern.test(requestId))
  ? null
  : { code: 'INVALID_SESSION', message: 'Reading the suggestions needs a valid conversation and request ID.' };
return [{ json: {
  valid: error === null, sessionId, requestId, filter,
  proposedInput: { sessionId, requestId, filter },
  ...(error ? { response: { ok: false, error } } : {}),
} }];

const input = $('Validate Read Input').first().json;
const rows = $input.all().map((item) => item.json).filter((row) => row && row.runId);

const minutesSince = (value) => {
  const parsed = Date.parse(String(value ?? ''));
  if (Number.isNaN(parsed)) return null;
  return Math.round((Date.now() - parsed) / 60000);
};
// Same number as the guard in 102: past the run workflow's own timeout, n8n
// has certainly stopped it, so a row still saying 'running' is wreckage.
const DEAD_AFTER = 31;

const finished = rows.filter((row) => ['completed', 'partial'].includes(String(row.status ?? '')));
const running = rows.filter((row) => String(row.status ?? '') === 'running')
  .map((row) => ({ ...row, age: minutesSince(row.startedAt) }))
  .filter((row) => row.age !== null);

const live = running.find((row) => row.age < DEAD_AFTER) ?? null;
const wreck = running.find((row) => row.age >= DEAD_AFTER) ?? null;
const latest = finished[0] ?? null;

return [{ json: { ...input,
  runId: latest ? String(latest.runId) : '',
  hasRun: latest !== null,
  running: live !== null,
  runningMinutes: live ? live.age : 0,
  interrupted: latest === null && wreck !== null,
  interruptedMinutes: wreck ? wreck.age : 0,
  run: latest ?? null } }];

const picked = $('Pick Run').first().json;
const rows = $input.all().map((item) => item.json).filter((row) => row && row.suggestionId);

if (!picked.hasRun) {
  const message = picked.running
    ? `A review has been running for ${picked.runningMinutes} minute${picked.runningMinutes === 1 ? '' : 's'} and has not finished yet. Say so and offer to read it back shortly.`
    : (picked.interrupted
      ? `A review started ${picked.interruptedMinutes} minutes ago and never finished, which usually means the agent restarted while it was working. Nothing was saved from it. Offer to run another one.`
      : 'No review has finished yet. Say so plainly and offer to run one, rather than guessing at what is in their books.');
  return [{ json: { ...picked, response: { ok: true, hasRun: false, running: picked.running,
    interrupted: picked.interrupted, suggestions: [], message } } }];
}

const money = (row) => {
  const value = Number(row.amount ?? 0);
  const sign = value < 0 ? '-' : '';
  return `${sign}$${Math.abs(value).toFixed(2)}`;
};
const who = (row) => String(row.contactName || row.suggestedContact || row.description || 'unnamed').slice(0, 60);
const line = (row) => `${String(row.occurredAt ?? '').slice(0, 10)}  ${money(row)}  ${who(row)}`;

// The groups are mutually exclusive by construction. A transaction shown in two
// of them reads as two transactions, and the one thing somebody going through
// their books cannot afford is to lose count.
const executed = rows.filter((row) => String(row.executionStatus ?? '') === 'created');
const done = new Set(executed);
const accepted = rows.filter((row) => !done.has(row) && String(row.userDecision ?? '') === 'accepted');
const decided = new Set([...done, ...accepted, ...rows.filter((row) => String(row.userDecision ?? '') !== '')]);
const uncertain = rows.filter((row) => !decided.has(row) && String(row.needsHuman ?? '') === 'yes');
const matchInXero = rows.filter((row) => !decided.has(row) && String(row.needsHuman ?? '') !== 'yes'
  && (String(row.matchedInvoiceId ?? '') !== '' || String(row.basis ?? '') === 'existing-match'));
const ready = rows.filter((row) => !decided.has(row) && String(row.needsHuman ?? '') !== 'yes'
  && String(row.matchedInvoiceId ?? '') === '' && String(row.basis ?? '') !== 'existing-match');

const render = (row, kind) => ({
  suggestionId: String(row.suggestionId),
  line: line(row),
  date: String(row.occurredAt ?? '').slice(0, 10),
  amount: money(row),
  counterparty: who(row),
  account: kind === 'ready' || kind === 'accepted' ? `${row.suggestedAccountCode} ${row.suggestedAccountName}`.trim() : '',
  taxType: kind === 'ready' || kind === 'accepted' ? String(row.suggestedTaxType ?? '') : '',
  createsNewContact: String(row.suggestedContactId ?? '') === '' && String(row.suggestedContact ?? '') !== '',
  invoice: String(row.matchedInvoiceNumber ?? ''),
  basis: String(row.basis ?? ''),
  whatToCheck: String(row.whatToCheck ?? ''),
  confidence: Number(row.confidence ?? 0),
  executionStatus: String(row.executionStatus ?? ''),
});

const wanted = {
  all: { uncertain, matchInXero, ready, accepted, executed },
  uncertain: { uncertain, matchInXero: [], ready: [], accepted: [], executed: [] },
  ready: { uncertain: [], matchInXero: [], ready, accepted: [], executed: [] },
  accepted: { uncertain: [], matchInXero: [], ready: [], accepted, executed: [] },
  executed: { uncertain: [], matchInXero: [], ready: [], accepted: [], executed },
}[picked.filter];

return [{ json: { ...picked, response: {
  ok: true,
  hasRun: true,
  runId: picked.runId,
  status: String(picked.run?.status ?? ''),
  reportText: String(picked.run?.reportText ?? ''),
  counts: { total: rows.length, uncertain: uncertain.length, matchInXero: matchInXero.length,
            ready: ready.length, accepted: accepted.length, executed: executed.length },
  needsYou: wanted.uncertain.map((row) => render(row, 'uncertain')),
  matchInXero: wanted.matchInXero.map((row) => render(row, 'match')),
  readyToPrepare: wanted.ready.map((row) => render(row, 'ready')),
  alreadyAccepted: wanted.accepted.map((row) => render(row, 'accepted')),
  alreadyCreated: wanted.executed.map((row) => render(row, 'accepted')),
  errorSummary: String(picked.run?.errorSummary ?? ''),
  nextStep: 'Read reportText back as it is written; it is already in plain language and in the right order. Lead with the ones that need them. Every line names the date, the exact amount and who it was with, because that is how somebody recognises a transaction. Never round an amount, and never say anything here is reconciled: it is reconciled when they click OK in Xero, and not before.',
} } }];

const input = $('Validate Read Input').first().json;
const response = $json.response ?? { ok: false, error: { code: 'TOOL_FAILED', message: 'The tool did not return a result.' } };
return { json: {
  occurredAt: new Date().toISOString(),
  sessionId: input.sessionId,
  requestId: input.requestId,
  toolName: 'get_reconciliation_suggestions',
  proposedInput: JSON.stringify(input.proposedInput ?? {}),
  result: JSON.stringify(response),
  error: response.ok === false ? String(response.error?.message ?? 'Tool failed') : '',
  response
} };

const prepared = $('Prepare Audit').first().json;
const response = { ...prepared.response };
if (!Number.isInteger($json.id)) {
  response.auditWarning = 'The tool result could not be written to the local audit table.';
}
return { json: response };
